<script setup>
import {computed} from 'vue';
import {money} from './domain.js';import {qty} from './procurement.js';
const props=defineProps(['order','modes']);const items=computed(()=>props.order.items?.length?props.order.items:[{description:props.order.description,amount:props.order.base}]);const date=s=>s?new Date(s+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
</script>
<template><div class="po-reference" v-if="modes.purchase_reference!=='hidden'"><div><small>Purchase order number</small><strong>{{order.purchaseOrderNumber||'Not linked'}}</strong></div><div><small>Purchase order date</small><strong>{{date(order.purchaseOrderDate)}}</strong></div></div><section class="panel mb-5"><div class="panel-top"><h2>Work-order items</h2><span class="small muted">Original amounts · including tax</span></div><div class="table-scroll"><table class="orders-table"><thead><tr><th v-if="modes.description!=='hidden'">DESCRIPTION OF ITEM</th><th v-if="modes.unit!=='hidden'">UNIT</th><th v-if="modes.period!=='hidden'">PERIOD</th><th v-if="modes.quantity!=='hidden'">QUANTITY</th><th v-if="modes.amount!=='hidden'">RATE</th><th v-if="modes.amount!=='hidden'">AMOUNT</th></tr></thead><tbody><tr v-for="(i,index) in items" :key="index"><td v-if="modes.description!=='hidden'" class="scope-cell">{{i.description}}</td><td v-if="modes.unit!=='hidden'">{{i.unit||'Not recorded'}}</td><td v-if="modes.period!=='hidden'">{{date(i.startDate)}} – {{date(i.endDate)}}</td><td v-if="modes.quantity!=='hidden'">{{i.quantityMilli==null?'Not recorded':qty(i.quantityMilli)}}</td><td v-if="modes.amount!=='hidden'">{{i.rate==null?'Not recorded':money(i.rate)}}</td><td v-if="modes.amount!=='hidden'"><strong>{{money(i.amount)}}</strong></td></tr></tbody></table></div></section></template>
